<script setup>
import { validateSection } from '../../utils/validation.js'
import { computed, nextTick, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { eventsApi } from '../../api/events.js'
import AdminToggle from '../../components/admin/AdminToggle.vue'
import { productsApi } from '../../api/products.js'
import { resolveApiUrl } from '../../api/client.js'
import EventContentEditor from '../../components/admin/EventContentEditor.vue'
import EventOperations from '../../components/admin/EventOperations.vue'

const { locale } = useI18n()
const fa = computed(() => locale.value === 'fa')
const tr = (en, faText) => fa.value ? faText : en
const events = ref([])
const draft = ref(null)
const busy = ref(false)
const notice = ref(''), timeError = ref('')
const editor = ref(null)
const uploadingCover = ref(false), uploadingMedia = ref(false), speakerQuery = ref(''), speakerOptions = ref([])
const phase = ref('all'), editorTab = ref('details'), contentLocale = ref('fa')
const filteredEvents = computed(() => phase.value === 'all' ? events.value : events.value.filter(item => item.status === phase.value))
const phases = computed(() => [{ key: 'all', name: tr('All', 'همه') }, { key: 'upcoming', name: tr('Upcoming', 'پیش رو') }, { key: 'live', name: tr('Live', 'زنده') }, { key: 'completed', name: tr('Past', 'گذشته') }])
const tabs = computed(() => [{ key: 'details', name: tr('Details & capacity', 'اطلاعات و ظرفیت') }, { key: 'content', name: tr('Page content', 'محتوای صفحه') }, { key: 'operations', name: tr('Live & reservations', 'لایو و رزروها') }])

const emptyTranslation = (code) => ({ locale: code, title: '', summary: '', description: '', host_label: '', content: {} })
const translation = (code) => draft.value.translations.find((item) => item.locale === code)
const localDate = (value) => { if (!value) return ''; const date = new Date(value); const pad = (n) => String(n).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}` }

const load = async () => { busy.value = true; try { events.value = (await eventsApi.adminList()).data } catch (error) { notice.value = error.message } finally { busy.value = false } }
const createEvent = () => {
  editorTab.value = 'details'
  const start = localDate(Date.now() + 86400000)
  const end = localDate(Date.now() + 93600000)
  draft.value = { id: null, slug: '', kind: 'online', status: 'upcoming', starts_at: start, ends_at: end, timezone: 'Asia/Tehran', capacity: null, online_url: '', venue: '', cover_url: '', agenda_steps: [], published: false, translations: [emptyTranslation('en'), emptyTranslation('fa')], speakers: [] }
}
const editEvent = (item) => { draft.value = JSON.parse(JSON.stringify(item)); draft.value.starts_at = localDate(item.starts_at); draft.value.ends_at = localDate(item.ends_at); draft.value.translations.forEach(t => { t.content ||= {} }); draft.value.speakers = (item.speakers || []).map((s) => ({ selection: s.partner_id ? `partner:${s.partner_id}` : s.profile_user_id, role_label: s.role_label, position: s.position })) }
const operationChanged = async () => { await load(); const saved = events.value.find(item => item.id === draft.value?.id); if (saved) editEvent(saved) }
const payload = () => ({
  ...(draft.value.id ? {} : { slug: draft.value.slug }), kind: draft.value.kind, status: draft.value.status,
  starts_at: new Date(draft.value.starts_at).toISOString(), ends_at: new Date(draft.value.ends_at).toISOString(),
  timezone: draft.value.timezone, capacity: draft.value.capacity ? Number(draft.value.capacity) : null,
  online_url: draft.value.online_url || null,
  venue: draft.value.venue || null,
  cover_url: draft.value.cover_url || null,
  agenda_steps: draft.value.agenda_steps.filter((step) => step.trim()),
  translations: draft.value.translations,
  speakers: draft.value.speakers.map((s, i) => ({
    ...(s.selection?.startsWith('partner:') ? { partner_id: s.selection.slice(8) } : { user_id: s.selection }),
    role_label: s.role_label, position: i + 1,
  })),
})
const save = async () => { timeError.value = draft.value.starts_at && draft.value.ends_at && new Date(draft.value.ends_at) <= new Date(draft.value.starts_at) ? tr('End time must be after start time.', 'زمان پایان باید بعد از زمان شروع باشد.') : ''; if (timeError.value) { editorTab.value = 'details'; return } for (const tab of ['details', 'content']) { editorTab.value = tab; await nextTick(); if (tab === 'content') { for (const code of ['fa', 'en']) { contentLocale.value = code; await nextTick(); if (!validateSection(editor.value.querySelector('nav').nextElementSibling.nextElementSibling)) return } } else if (!validateSection(editor.value.querySelector('nav').nextElementSibling)) return } busy.value = true; notice.value = ''; try { const result = draft.value.id ? await eventsApi.adminUpdate(draft.value.id, payload()) : await eventsApi.adminCreate(payload()); if (!result.data?.approval) editEvent(result.data); notice.value = result.data?.approval ? tr('Sent to the principal approval queue.', 'درخواست به صف تأیید مدیر اصلی ارسال شد.') : tr('Event saved.', 'رویداد ذخیره شد.'); await load() } catch (error) { notice.value = error.message } finally { busy.value = false } }
const toggle = async (item) => { try { const result = await (item.published ? eventsApi.adminUnpublish(item.id) : eventsApi.adminPublish(item.id)); if (result.data?.approval) notice.value = tr('Change sent for approval.', 'تغییر برای تأیید ارسال شد.'); else if (draft.value?.id === item.id) draft.value.published = result.data.published; await load() } catch (error) { notice.value = error.message } }
const archive = async (item) => { if (!confirm(tr('Remove this event from the website? Use Completed to keep its past-event page.', 'رویداد از سایت حذف شود؟ برای حفظ صفحهٔ رویداد گذشته، وضعیت را «پایان‌یافته» انتخاب کنید.'))) return; try { const result = await eventsApi.adminArchive(item.id); if (result?.data?.approval) notice.value = tr('Change sent for approval.', 'تغییر برای تأیید ارسال شد.'); else draft.value = null; await load() } catch (error) { notice.value = error.message } }
const findSpeakers = async () => { try { speakerOptions.value = (await eventsApi.speakerOptions(speakerQuery.value)).data } catch (error) { notice.value = error.message } }
const addSpeaker = () => draft.value.speakers.push({ selection: '', role_label: '', position: draft.value.speakers.length + 1 })
const uploadCover = async (event) => { const file = event.target.files?.[0]; if (!file) return; uploadingCover.value = true; try { draft.value.cover_url = (await productsApi.upload(file)).data.url } catch (problem) { notice.value = problem.message } finally { uploadingCover.value = false; event.target.value = '' } }
const cover = (url) => url?.startsWith('/api/') ? resolveApiUrl(url) : url
onMounted(() => { load(); findSpeakers() })
</script>

<template>
  <div>
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="admin-eyebrow">{{ tr('Programme content', 'محتوای برنامه‌ها') }}</p><h2 class="admin-h1 mt-2">{{ tr('Events', 'رویدادها') }}</h2><p class="mt-2 text-sm text-ink-muted">{{ tr('Online and onsite events, bilingual copy, capacity and speakers.', 'رویدادهای آنلاین و حضوری، محتوای دوزبانه، ظرفیت و سخنران‌ها.') }}</p></div><button class="admin-btn admin-btn-primary" @click="createEvent">{{ tr('Add event', 'افزودن رویداد') }}</button></div>
    <div class="mt-7 flex flex-wrap gap-2"><button v-for="item in phases" :key="item.key" class="admin-btn admin-btn-sm" :class="phase===item.key?'admin-btn-primary':'admin-btn-ghost'" @click="phase=item.key">{{ item.name }} · {{ item.key==='all'?events.length:events.filter(e=>e.status===item.key).length }}</button></div><div class="admin-card mt-4 p-6 overflow-x-auto"><table class="admin-table min-w-[760px]"><thead><tr><th>{{ tr('Event', 'رویداد') }}</th><th>{{ tr('Kind', 'نوع') }}</th><th>{{ tr('Status', 'وضعیت') }}</th><th>{{ tr('Start', 'شروع') }}</th><th>{{ tr('Capacity', 'ظرفیت') }}</th><th>{{ tr('Published', 'انتشار') }}</th><th></th></tr></thead><tbody><tr v-for="item in filteredEvents" :key="item.id"><td><strong>{{ item.title }}</strong><br><small>{{ item.slug }}</small></td><td>{{ item.kind }}</td><td>{{ item.status }}</td><td>{{ new Date(item.starts_at).toLocaleString(locale) }}</td><td>{{ item.reserved }} / {{ item.capacity ?? '∞' }}</td><td><AdminToggle :model-value="item.published" @update:model-value="toggle(item)" /></td><td><button class="admin-btn admin-btn-ghost admin-btn-sm" @click="editEvent(item)">{{ tr('Edit', 'ویرایش') }}</button></td></tr></tbody></table><p v-if="!busy&&!filteredEvents.length" class="py-8 text-center text-ink-muted">{{ tr('No events yet.', 'هنوز رویدادی وجود ندارد.') }}</p></div>

    <p v-if="notice && !draft" role="status" class="mt-3 text-sm text-ink-muted">{{ notice }}</p>
    <section id="content-editor" v-if="draft" ref="editor" class="admin-card mt-7 p-6 md:p-8 space-y-6">
      <div class="flex justify-between"><h3 class="admin-h2">{{ draft.id ? tr('Edit event', 'ویرایش رویداد') : tr('New event', 'رویداد جدید') }}</h3><button class="admin-btn admin-btn-ghost admin-btn-sm" @click="draft=null">{{ tr('Close', 'بستن') }}</button></div>
      <nav class="flex flex-wrap gap-2 border-b border-parchment-deep pb-4"><button v-for="tab in tabs" :key="tab.key" type="button" class="admin-btn admin-btn-sm" :class="editorTab===tab.key?'admin-btn-primary':'admin-btn-ghost'" :disabled="tab.key==='operations' && !draft.id" @click="editorTab=tab.key">{{ tab.name }}</button></nav><div v-show="editorTab === 'details'" class="space-y-6"><div class="grid md:grid-cols-4 gap-4"><label><span class="admin-label">Slug</span><input required v-model="draft.slug" :disabled="!!draft.id" class="admin-input" dir="ltr"></label><label><span class="admin-label">{{ tr('Kind', 'نوع') }}</span><select v-model="draft.kind" class="admin-select"><option value="online">Online</option><option value="onsite">Onsite</option></select></label><label><span class="admin-label">{{ tr('Status', 'وضعیت') }}</span><select v-model="draft.status" class="admin-select"><option value="upcoming">Upcoming</option><option value="live">Live</option><option value="completed">Completed</option></select></label><label><span class="admin-label">{{ tr('Capacity', 'ظرفیت') }}</span><input v-model.number="draft.capacity" type="number" min="1" class="admin-input"></label></div>
      <div class="grid md:grid-cols-4 gap-4"><label><span class="admin-label">{{ tr('Starts at (your local time)', 'زمان شروع (به وقت دستگاه شما)') }}</span><input required v-model="draft.starts_at" type="datetime-local" class="admin-input"></label><label><span class="admin-label">{{ tr('Ends at (your local time)', 'زمان پایان (به وقت دستگاه شما)') }}</span><input required v-model="draft.ends_at" type="datetime-local" class="admin-input" @input="timeError=''"><p v-if="timeError" class="field-error" role="alert">{{ timeError }}</p></label><label><span class="admin-label">Timezone</span><input required v-model="draft.timezone" class="admin-input" dir="ltr"></label><label><span class="admin-label">{{ draft.kind==='online' ? 'URL' : tr('Venue','محل') }}</span><input v-if="draft.kind==='online'" :required="draft.status === 'live' && draft.kind === 'online'" v-model="draft.online_url" type="url" class="admin-input" dir="ltr"><input v-else required v-model="draft.venue" class="admin-input"></label></div>
      <label v-if="draft.kind === 'onsite'" class="block max-w-xl"><span class="admin-label">{{ tr('Optional live stream URL', 'لینک پخش زنده (اختیاری)') }}</span><input :required="draft.status === 'live' && draft.kind === 'online'" v-model="draft.online_url" type="url" class="admin-input" dir="ltr"></label>
      <label v-if="draft.kind === 'online'" class="block max-w-xl"><span class="admin-label">{{ tr('Live hub venue or location (optional)', 'محل یا توضیح مکان لایو (اختیاری)') }}</span><input v-model="draft.venue" maxlength="500" class="admin-input"></label>
      <div class="admin-panel p-5"><h4 class="admin-h2">{{ tr('Event media', 'رسانهٔ رویداد') }}</h4><div class="mt-4 grid gap-4 md:grid-cols-[1fr,auto]"><label><span class="admin-label">{{ tr('Cover image URL', 'آدرس تصویر اصلی') }}</span><input v-model="draft.cover_url" type="text" pattern="(https?://.*|/api/v1/files/[0-9a-fA-F-]{36})" class="admin-input" dir="ltr"></label><label class="admin-btn admin-btn-ghost cursor-pointer self-end">{{ uploadingCover ? tr('Uploading…','در حال بارگذاری…') : tr('Upload cover','بارگذاری تصویر') }}<input type="file" accept="image/png,image/jpeg,image/webp" class="sr-only" @change="uploadCover"></label></div><img v-if="draft.cover_url" :src="cover(draft.cover_url)" alt="" class="mt-3 h-28 w-44 rounded-lg object-cover"><p class="mt-3 text-xs text-ink-muted">{{ tr('For live events, enter a secure stream link above. YouTube, Vimeo, Aparat and direct video links are supported.', 'برای رویداد زنده، لینک امن پخش را در فیلد بالا وارد کنید. یوتیوب، ویمئو، آپارات و لینک مستقیم ویدئو پشتیبانی می‌شوند.') }}</p></div>
      <div class="admin-panel p-5"><div class="flex items-center justify-between"><h4 class="admin-h2">{{ tr('Live session steps', 'مراحل برنامهٔ زنده') }}</h4><button type="button" class="admin-btn admin-btn-ghost admin-btn-sm" @click="draft.agenda_steps.push('')">{{ tr('Add step', 'افزودن مرحله') }}</button></div><div v-for="(step, index) in draft.agenda_steps" :key="index" class="mt-3 flex gap-3"><span class="self-center text-xs text-ink-muted">{{ index + 1 }}</span><input required v-model="draft.agenda_steps[index]" maxlength="240" class="admin-input"><button type="button" class="admin-btn admin-btn-danger admin-btn-sm" @click="draft.agenda_steps.splice(index, 1)">×</button></div></div>
      <div v-for="code in ['en','fa']" :key="code" class="admin-panel p-5 space-y-4" :dir="code==='fa'?'rtl':'ltr'"><h4 class="admin-label">{{ code.toUpperCase() }}</h4><input required maxlength="240" v-model="translation(code).title" class="admin-input" :placeholder="tr('Title','عنوان')"><input required maxlength="240" v-model="translation(code).host_label" class="admin-input" :placeholder="tr('Host label','برگزارکننده')"><input required maxlength="500" v-model="translation(code).summary" class="admin-input" :placeholder="tr('Summary','خلاصه')"><textarea required maxlength="20000" v-model="translation(code).description" rows="5" class="admin-textarea" :placeholder="tr('Description','توضیحات')"></textarea></div>
      <div><div class="flex justify-between"><h4 class="admin-h2">{{ tr('Speakers & organizers', 'سخنران‌ها و برگزارکنندگان') }}</h4><button class="admin-btn admin-btn-ghost admin-btn-sm" @click="addSpeaker">{{ tr('Add speaker', 'افزودن سخنران') }}</button></div><div class="mt-4 flex gap-3"><input v-model="speakerQuery" class="admin-input" :placeholder="tr('Search members and site partners by name','جست‌وجوی اعضا و همکاران سایت')" @keydown.enter.prevent="findSpeakers"><button type="button" class="admin-btn admin-btn-ghost" @click="findSpeakers">{{ tr('Search','جست‌وجو') }}</button></div><div v-for="(speaker,index) in draft.speakers" :key="index" class="admin-panel p-4 mt-3 grid md:grid-cols-[1fr,1fr,auto] gap-3 items-end"><label><span class="admin-label">{{ tr('Speaker','سخنران') }}</span><select required v-model="speaker.selection" class="admin-select"><option value="">{{ tr('Choose a person','انتخاب فرد') }}</option><option v-if="speaker.selection && !speakerOptions.some(p=>p.id===speaker.selection)" :value="speaker.selection">{{ events.find(e=>e.id===draft.id)?.speakers.find(s=>(s.partner_id ? `partner:${s.partner_id}` : s.profile_user_id)===speaker.selection)?.name || tr('Selected speaker','سخنران انتخاب‌شده') }}</option><option v-for="person in speakerOptions" :key="person.id" :value="person.id">{{ person.name }} · {{ person.kind === 'partner' ? tr('Partner', 'همکار') : tr('Member', 'عضو') }}</option></select></label><label><span class="admin-label">{{ tr('Role', 'نقش') }}</span><input required maxlength="160" v-model="speaker.role_label" class="admin-input"></label><button class="admin-btn admin-btn-danger admin-btn-sm" @click="draft.speakers.splice(index,1)">×</button></div></div>
      </div><div v-if="editorTab === 'content'" class="space-y-5"><div class="flex gap-2"><button v-for="code in ['fa','en']" :key="code" class="admin-btn admin-btn-sm" :class="contentLocale===code?'admin-btn-primary':'admin-btn-ghost'" @click="contentLocale=code">{{ code==='fa'?'فارسی':'English' }}</button></div><EventContentEditor :key="contentLocale" :content="translation(contentLocale).content" @uploading="uploadingMedia=$event" :dir="contentLocale === 'fa' ? 'rtl' : 'ltr'" /></div><EventOperations v-if="editorTab === 'operations' && draft.id" :key="draft.id" :event="draft" @changed="operationChanged" /><div v-if="editorTab !== 'operations'" class="flex gap-3"><button class="admin-btn admin-btn-primary" :disabled="busy || uploadingCover || uploadingMedia" @click="save">{{ tr('Save', 'ذخیره') }}</button><button v-if="draft.id" class="admin-btn admin-btn-danger" @click="archive(draft)">{{ tr('Remove from site', 'حذف از سایت') }}</button></div>
      <p v-if="notice" role="status" class="mt-3 text-sm text-ink-muted">{{ notice }}</p>
    </section>
  </div>
</template>


